from lesson_helpers import *
from bs4 import BeautifulSoup
import re
pops=[]
def add(k,title,body,ids):pops.append('<template data-pop="'+k+'" data-title="'+html.escape(title,quote=True)+'">'+body+ref(*ids)+'</template>')
def concept(k,title,p1,p2,ids):add('g24-'+k,title,'<p>'+p1+'</p><p>'+p2+'</p>',ids)
concept('definition','Dystonie : décrire le phénomène','Mouvements ou postures anormaux, soutenus ou intermittents, souvent organisés en motifs répétitifs ; ils peuvent être tremblants ou saccadés. L’action peut les déclencher ou les aggraver.','La torsion n’est pas indispensable dans chaque forme. Le terme décrit un trouble du mouvement et ne prouve ni lésion musculaire primitive, ni cause génétique unique.',('INT-MDS-DEF','INT-MDS-AXIS2'))
concept('pattern','Un motif moteur répétitif','Décrire direction, régions et conditions de survenue, avec une tâche sûre et reproductible. Un mouvement organisé en motif n’est pas simplement toute secousse ou toute douleur.','Observer aussi les autres dimensions : force, tonus, réflexes, coordination et retentissement. La description aide au diagnostic sans identifier seule une cause.',('INT-MDS-DEF','CH-PROFILES'))
concept('geste','Geste atténuateur','Certaines manœuvres volontaires améliorent brièvement une posture ; un contact léger au menton peut illustrer une forme cervicale. Décrire l’effet observé et sa durée.','Ce signe peut aider mais n’est pas obligatoire ni une preuve étiologique universelle. Une photo ne montre pas l’avant/après ; l’examen dynamique reste nécessaire.',('INT-MDS-PHENO','CH-USZ-CLIN'))
concept('overflow','Débordement','Un mouvement dystonique peut s’étendre à un segment voisin apparemment non concerné et sans rapport approprié avec le geste voulu. Il faut examiner au-delà de la région dont le patient se plaint.','Le phénomène contribue à la description clinique ; il ne signifie pas automatiquement progression à une forme généralisée ni atteinte d’un gène particulier.',('INT-MDS-PHENO','INT-MDS-DISTR'))
concept('mirror','Dystonie en miroir','Une tâche réalisée du côté non atteint peut provoquer une posture dystonique dans le membre atteint au repos, souvent avec la tâche habituellement gênante.','Cela diffère d’un mouvement en miroir reproduisant simplement le mouvement controlatéral. Le mot miroir doit correspondre à ce qui est réellement observé.',('INT-MDS-PHENO',))
concept('fixed','Posture soutenue ou fixée','Le consensus distingue une posture soutenue au repos mais mobilisable passivement et une posture persistante peu modifiable par mobilisation passive. Respecter douleur et sécurité.','Le caractère fixé ne démontre pas seul une cause fonctionnelle ou mécanique. L’ensemble du tableau et les diagnostics concurrents doivent être examinés.',('INT-MDS-PHENO','INT-MDS-AXIS2'))
concept('classification','Deux axes, deux questions','L’axeI décrit âge de début, famille, distribution, temporalité, phénoménologie et signes associés. L’axeII organise causes génétiques/acquises, anatomie et mécanismes.','Ces axes ne dictent pas seuls le code. La CIM suisse conserve des libellés et inclusions propres, dont la dyskinésie tardive enG24.0 et les frontièresG80.3/M43.6.',('INT-MDS-AXIS1','INT-MDS-AXIS2','CH-CIM','CH-CIM-BOUND'))
concept('distribution','Distribution révisée2025','Focale : une région ; segmentaire : deux ou trois contiguës ; multifocale : deux ou trois non contiguës ; hémidystonie : membres supérieur et inférieur d’un même côté.','Généralisée dépasse les schémas précédents sans être hémidystonie. Tronc avec deux autres régions ou trois/quatre membres sans tronc sont des exemples ; une règle mécanique>3régions est insuffisante.',('INT-MDS-DISTR',))
concept('combined','Isolée ou combinée','Des signes neurologiques ou systémiques pertinents peuvent faire classer combinée : autre mouvement distinct, signes pyramidaux, développement ou atteinte hépatique, par exemple.','Une douleur ou une anxiété ne change pas à elle seule une dystonie cervicale isolée en combinée. Un mouvement dystonique tremblant peut aussi être différent d’un tremblement indépendant.',('INT-MDS-PHENO','INT-MDS-AXIS1'))
concept('etiology','Étiologie : cause et niveau de preuve','Une dystonie peut être liée à une cause génétique, une exposition, une lésion, une maladie métabolique ou un autre mécanisme. Des catégories peuvent se recouvrir.','Une imagerie normale ou une histoire familiale négative ne suffisent pas à expliquer la cause. Décrire l’hypothèse, les arguments et les incertitudes puis choisir des investigations utiles.',('INT-MDS-AXIS2','EU-ERN-ADULT'))
concept('history','Le premier symptôme moteur','Dater région initiale, tâche, installation et évolution, en distinguant âge actuel et âge du début moteur. Rechercher variations diurnes, effet du sommeil, famille et signes associés.','Reprendre aussi tous les médicaments, les changements et dernières prises réelles. Une ordonnance ou une photo isolée ne donne pas la chronologie.',('INT-MDS-AXIS1','FI-PAS','CH-HUG'))
concept('task','Spécifique d’une tâche','Certaines formes surviennent surtout pendant écriture, jeu instrumental ou une autre activité précise. Observer la tâche quand cela est possible et sûr.','La difficulté ne se résume pas à une faiblesse ou un manque d’entraînement. Décrire le motif, sa reproductibilité et le retentissement ; une adaptation de tâche fait partie du plan individualisé.',('INT-MDS-AXIS1','CH-USZ-CLIN','CH-USZ-TX'))
concept('exam','Comparer des conditions','Observer repos, posture et action ; rechercher geste atténuateur, débordement et signes associés. Examiner aussi force, réflexes, tonus, coordination et nerfs crâniens.','En cas d’instabilité, la sécurité précède une classification détaillée. Documenter les limites de l’examen et refaire une évaluation utile dans la trajectoire.',('CH-PROFILES','INT-MDS-PHENO','EU-ERN-ADULT'))
concept('drug','Médicament causal','Les neuroleptiques et certains autres agents peuvent provoquer des troubles extrapyramidaux. La FI du métoclopramide décrit dystonie aiguë et crise oculogyre même après une dose, particulièrement chez enfant/adulte jeune.','Nom, indication, dose, durée et chronologie doivent être retrouvés. Le produit responsable n’est pas toujours prescrit pour une maladie neurologique ou psychiatrique.',('FI-PAS','FI-AKI','INT-MDS-AXIS2'))
concept('acute','Dystonie aiguë médicamenteuse','Une posture cervicale, faciale, linguale ou une crise oculogyre après exposition impose d’évaluer la sécurité et l’hypothèse causale. Une difficulté de déglutition ou respiration change le circuit urgent.','Revoir le produit avec l’équipe ; le bipéridène peut relever de sa FI dans un contexte évalué. Cela ne constitue pas le traitement universel d’une dyskinésie tardive ou d’un syndrome malin.',('FI-PAS','FI-AKI','BOT-IMMUNO'))
concept('tardive','Dyskinésie tardive etG24.0','La nomenclature inclut dyskinésie tardive sousG24.0. Cette inclusion ne signifie pas que tous les phénomènes médicamenteux ont la même temporalité, le même mécanisme ou le même traitement.','La FI Akineton précise qu’il peut aggraver une dyskinésie tardive. Le métoclopramide peut aussi entraîner un syndrome tardif potentiellement irréversible ; réévaluer la conduite avec expertise.',('CH-CIM','FI-AKI','FI-PAS'))
concept('storm','Crise dystonique sévère','Le schéma thérapeutique ERN distingue la crise dystonique des formes stables et prévoit une prise en charge intensive, avec options spécialisées de secours.','Une aggravation diffuse épuisante, un problème respiratoire ou une défaillance générale ne doit pas attendre une visite de routine. Chercher aussi déclencheur, exposition et diagnostics concurrents.',('EU-ERN-TX','FI-PAS'))
concept('airway','Respirer et déglutir','Évaluer rapidement une difficulté nouvelle à parler, avaler ou respirer. Le contexte peut être une réaction médicamenteuse, une complication de toxine ou une autre maladie urgente.','Après injection, une diffusion peut affecter des muscles à distance et entraîner aspiration ou détresse respiratoire. Le patient et l’entourage doivent connaître les signes à signaler immédiatement.',('BOT-IMMUNO','FI-XEOMIN','FI-BOTOX','FI-DYSPORT','FI-PAS'))
concept('imaging','Imagerie orientée','L’imagerie recherche une lésion pertinente selon âge, début et signes associés. Certaines dystonies idiopathiques n’ont pas d’anomalie détectable en imagerie clinique.','La normalité ne prouve pas une origine fonctionnelle ; une lésion doit aussi être concordante. Le parcours pédiatrique et la démarche adulte n’imposent pas le même bilan automatique à tout patient.',('INT-MDS-AXIS2','EU-ERN-ADULT','EU-ERN-CHILD'))
concept('genetics','Génétique et conseil','Âge, famille, distribution et signes associés orientent les analyses. Une histoire familiale négative n’exclut pas une cause génétique ; un variant s’interprète avec le phénotype et le conseil.','La revue monogénique européenne2026 soutient la génétique avant stimulation et une mesure systématique des résultats. Elle n’offre pas une prédiction individuelle universelle à partir d’un seul nom de gène.',('INT-MDS-AXIS2','EU-DBS-COUNSEL','EU-DBS-LIMIT'))
concept('wilson','Wilson : traiter la maladie et ses symptômes','Une dystonie, notamment avec signes hépatiques ou neuropsychiatriques, peut justifier une démarche spécialisée de Wilson. Plusieurs examens et arguments s’intègrent ; un seul dosage ne décide pas.','Le traitement causal anti-cuivre et les traitements symptomatiques peuvent être complémentaires. Une injection locale ne remplace pas le traitement de la maladie, et un chélateur ne se prescrit pas au seul codeG24.',('EU-EASL-DX','EU-EASL-SYM'))
concept('dopa','Dopa-sensibilité : une cause traitable','Un trouble de synthèse dopaminergique peut produire un tableau dystonique, parfois avec marche et variation diurne. Le parcours pédiatrique européen prévoit un essai spécialisé dans une démarche de causes traitables.','Produit, protocole et statut réglementaire sont vérifiés. La FI suisse Madopar contre-indique les moins de25ans : un essai pédiatrique n’est donc pas une application automatique de cette FI.',('NORMAL-GCH1','NORMAL-TH','EU-ERN-CHILD','FI-MAD'))
concept('gch1','GCH1, BH4 et tyrosinehydroxylase','La GTPcyclohydrolase1 participe à la biosynthèse du cofacteurBH4. La tyrosinehydroxylase utilise ce cofacteur et l’oxygène pour produireL-DOPA à partir de tyrosine.','C’est un exemple mécanistique, pas une explication de toutes les dystonies. Une photographie de neurone ne mesure ni cette voie ni un déficit ; aucune dose de médicament ne se déduit de l’équation.',('NORMAL-GCH1','NORMAL-TH','IMG-HISTO'))
concept('toxin','Une action périphérique locale','La toxine botuliqueA diminue la libération d’acétylcholine par action sur une terminaison présynaptique, notamment clivage deSNAP-25. Le muscle reçoit moins de signal.','Le traitement peut soulager un phénomène focal sans guérir sa cause centrale. Une faiblesse excessive ou une diffusion peut être indésirable ; produit, indication, anatomie et surveillance comptent.',('BOT-MECH','FI-BOTOX','FI-XEOMIN','FI-DYSPORT'))
concept('units','Les unités restent celles du produit','Les méthodes et unités d’activité des toxines sont spécifiques. Une même valeur numérique deBOTOX, Xeomin etDysport ne représente pas une prescription interchangeable.','Les plafonds et intervalles sont aussi propres à l’indication. Pour cervicale dans les FI lues : BOTOX≤300U avec≥10semaines, Xeomin≤300U avec≥8semaines, Dysport≤500U avec≥12semaines ; début et précautions restent à vérifier.',('FI-BOTOX','FI-XEOMIN','FI-DYSPORT'))
concept('dilution','Concentration et volume, après choix clinique','Exemple fictif attribué àDysport :500U reconstituées avec2,5mL de solvant donnent200U/mL. Une quantité déjà retenue de40U correspond à40÷200=0,2mL.','Le calcul ne choisit pas dose, muscles, sites ou intervalle. Une autre concentration change le volume ; une autre marque change aussi le sens des unités. Suivre préparation, solvant et conservation propres au flacon.',('FI-DYSPORT',))
concept('akineton','Bipéridène : indication et limites','Akineton a des indications extrapyramidales, avec schéma aigu injectable adulte et titration orale distincts. La FI précise formes et populations, cognition et risques anticholinergiques.','Ne pas traiter automatiquement toute posture avec lui : dyskinésie tardive peut être aggravée, données pédiatriques limitées, rein/foie sans expérience chiffrée, grossesse/allaitement à vérifier.',('FI-AKI','FI-PAS','CH-CIM'))
concept('dbs','Stimulation : sélectionner et mesurer','La stimulation peut être discutée pour des formes gênantes sélectionnées après insuffisance des traitements adaptés. Le choix ne repose pas uniquement sur le nom du noyau cible.','La revue européenne2026 des dystonies monogéniques souligne génétique, hétérogénéité et résultats rapportés par patient. Aucun pourcentage unique ne garantit le résultat pour toutes les causes deG24.',('EU-DBS-COUNSEL','EU-DBS-LIMIT','EU-ERN-TX','IMG-BASAL'))
concept('antibodies','Réponse moindre : plusieurs explications','Des anticorps peuvent contribuer à une baisse de réponse à une toxine et des injections trop rapprochées peuvent favoriser leur formation. Ce n’est pas la seule explication.','Revoir diagnostic, muscles, dose, technique, délai et évolution. Une difficulté respiratoire ou de déglutition correspond à une question de sécurité urgente, pas à une simple inefficacité immunologique.',('BOT-IMMUNO','FI-BOTOX','FI-XEOMIN','FI-DYSPORT'))
concept('pregnancy','Grossesse et allaitement : plusieurs décisions','Les FI des toxines déconseillent l’usage pendant grossesse sauf nécessité clairement évaluée et ne recommandent pas l’allaitement sous ces produits. Les mots exacts diffèrent selon préparation.','Une maladie causale telle que Wilson a son propre plan ; la gestion du traitement anti-cuivre ne se déduit pas des précautions d’une toxine. Décider avec les équipes plutôt qu’appliquer une consigne uniforme à tous médicaments.',('FI-BOTOX','FI-XEOMIN','FI-DYSPORT','EU-EASL-SYM'))
concept('child','Enfant : âge et indication','Le début précoce appelle une démarche neuropédiatrique avec causes acquises, métaboliques traitables et génétiques. Le document ERN2026 reprend une branche pédiatrique issue de2015, distincte de sa révision adulte.','Une indication pédiatrique de spasticité ou de sialorrhée n’est pas une autorisation générale de dose cervicale adulte. Vérifier chaque produit et le statut de l’essai de lévodopa.',('EU-ERN-CHILD','FI-XEOMIN','FI-DYSPORT','FI-MAD','FI-AKI'))
concept('scales','Score et fonction','TWSTRS etTsui décrivent la dystonie cervicale ; Fahn-Marsden et outils adaptés concernent d’autres distributions ou âges. Choisir le bon outil et des conditions comparables.','Ajouter objectifs du patient, autonomie, douleur, participation et effets indésirables. Des points gagnés ne deviennent pas automatiquement une guérison ni un pourcentage comparable entre échelles.',('EU-ERN-SCALES','EU-DBS-COUNSEL'))
concept('follow','Une trajectoire réévaluable','Suivre distribution, tâche, retentissement et tolérance. Après toxine, noter intensité de réponse, durée et effets ; après stimulation, mesurer aussi les résultats rapportés par le patient.','Une réponse incomplète demande réévaluation plutôt que surenchère automatique. La cause, les comorbidités et la faisabilité du plan peuvent évoluer.',('CH-HUG','EU-ERN-SCALES','EU-DBS-COUNSEL','BOT-IMMUNO'))
concept('prevention','Prévenir ce qui est évitable','Il n’existe pas de prévention universelle de toutes les dystonies. On peut reconnaître des expositions à risque, détecter des effets précoces et organiser une prescription plus sûre.','La FI Paspertin limite ses indications/durées et décrit des réactions même après une dose. Une limite propre à ce produit ne se transfère pas à tous les médicaments neurologiques.',('FI-PAS','CH-USZ-EPI','CH-HUG'))
summary=[('Décrire le mouvement puis établir cause et code.','INT-MDS-DEF'),('Prévalences historiques et estimations générales ne sont pas une incidence suisse actuelle.','EU-ESDE'),('Réseau central, voie biochimique et effecteur périphérique sont des niveaux distincts.','INT-MDS-AXIS2'),('Sécurité et urgence précèdent le détail de la classification.','EU-ERN-TX'),('La chronologie inclut tâche, âge du début, famille et médicaments réels.','INT-MDS-AXIS1'),('Observer plusieurs conditions et rechercher les signes associés.','INT-MDS-PHENO'),('La distribution révisée ne se réduit pas à>3régions et les signes associés sont décrits.','INT-MDS-DISTR'),('Le diagnostic du phénomène est clinique ; la cause demande ses propres arguments.','INT-MDS-AXIS2'),('Choisir les examens qui changent la conduite, selon âge et syndrome.','EU-ERN-ADULT'),('Distinguer phénomène, mimic, exposition et cause traitable.','EU-ERN-CHILD'),('Cause, symptômes et fonction guident des options différentes.','EU-ERN-TX'),('Mesurer symptômes, autonomie, tolérance et objectifs du patient.','EU-ERN-SCALES'),('Conserver produit, indication, population et unités dans chaque décision.','FI-DYSPORT'),('Une étiquette ou une image ne remplace pas une décision clinique étayée.','CH-CIM-BOUND')]
path=CH/'G24_a.html';txt=path.read_text()
for i,(essential,sid) in enumerate(summary,1):
 m=re.search(r'(<section\b[^>]*id="g24-'+str(i)+r'"[^>]*>)(.*?)(</section>)',txt,re.S);assert m
 soup=BeautifulSoup(m[2],'html.parser');title=soup.find(['h2','h3']).get_text(' ',strip=True);paras=re.findall(r'<p>(.*?)</p>',m[2],re.S)[:2];refs=list(dict.fromkeys(a.get_text().split(' — ')[0] for a in soup.select('a[data-reference-source]')))
 add('g24-exp-'+str(i),'Comprendre — '+title,'<p><b>Lecture expliquée.</b> '+essential+'</p>'+''.join('<p>'+p+'</p>' for p in paras),refs)
 add('pareto-g24-'+str(i),'Essentiel — '+title,'<p>'+essential+'</p>'+key('Décrire le phénomène, la cause et la décision avec leurs limites.'),(sid,))
 entry='<p>'+w('exp-'+str(i),'Comprendre ce point')+' <button class="pareto-btn ui" data-k="pareto-g24-'+str(i)+'">▲ Loi de Pareto — l’essentiel</button></p>';txt=txt[:m.end(2)]+entry+txt[m.end(2):]
cases=[('Une main pendant écriture','Une personne ne peut plus écrire sans une position anormale répétitive des doigts, alors que d’autres gestes restent possibles. Décrire la tâche et observer le motif avant de conclure à une compression nerveuse ou à une faiblesse.','Examiner aussi force, réflexes, autres régions et médicaments. L’adaptation de tâche et les traitements symptomatiques se choisissent selon diagnostic et retentissement.',('INT-MDS-DEF','INT-MDS-AXIS1','CH-PROFILES','CH-USZ-TX')),('Un antiémétique et une posture cervicale','Après un antiémétique, une personne présente une posture cervicale et une gêne linguale. Le métoclopramide peut provoquer une dystonie même après une dose.','Évaluer immédiatement déglutition et respiration, revoir l’exposition et traiter avec l’équipe. Ne pas confondre cet aigu avec une dyskinésie tardive pour laquelle un anticholinergique peut être défavorable.',('FI-PAS','FI-AKI','CH-CIM')),('Un enfant moins à l’aise le soir','Un enfant présente un trouble de marche avec posture anormale plus marquée en fin de journée. Un profil dopa-sensible peut être discuté, sans être prouvé par cette seule histoire.','Parcours neuropédiatrique, examen et bilan de causes traitables/génétiques. Un essai spécialisé ne devient pas une prescription automatique deMadopar, contre-indiqué avant25ans dans la FI suisse lue.',('NORMAL-GCH1','EU-ERN-CHILD','FI-MAD')),('Dysphagie après toxine','Une personne traitée pour dystonie cervicale signale une difficulté nouvelle à avaler. Il faut envisager une complication et rechercher respiration, faiblesse et risque d’aspiration.','Faire évaluer immédiatement ; ne pas simplement avancer une nouvelle injection ou convertir les unités d’une autre marque. Reprendre produit, dose, muscles, date et tolérance.',('FI-BOTOX','FI-XEOMIN','FI-DYSPORT','BOT-IMMUNO'))]
for i,(title,p1,p2,refs) in enumerate(cases,1):add('g24-cas-'+str(i),'Cas '+str(i)+' — '+title,'<p><b>Exercice fictif original.</b></p><p>'+p1+'</p><p>'+p2+'</p>',refs)
quiz=[('Dans le consensus2025, tronc et deux autres régions peuvent-ils relever d’une forme généralisée ?','Oui, c’est un des exemples, hors schéma d’hémidystonie.','Non, il faut toujours plus de trois régions.','La définition révisée dépasse les schémas segmentaire/multifocal sans être hémidystonie.','INT-MDS-DISTR'),('Une difficulté nouvelle à avaler après toxine demande-t-elle une évaluation immédiate ?','Oui, une complication avec risque respiratoire ou d’aspiration est possible.','Non, attendre seulement la prochaine séance.','Informer patient et entourage des signes de diffusion à signaler immédiatement.','BOT-IMMUNO'),('Peut-on convertir directement les unités de Dysport en unités de Xeomin ?','Non, les unités et les limites restent propres à chaque produit.','Oui, toute toxine de même type utilise les mêmes unités.','La concentration permet un volume pour le produit identifié, sans créer d’équivalence de puissance.','FI-DYSPORT'),('L’inclusion de dyskinésie tardive sous G24.0 justifie-t-elle toujours du bipéridène ?','Non, ce médicament peut aggraver une dyskinésie tardive.','Oui, le code suffit à choisir le traitement.','Le phénomène clinique et le contexte déterminent la conduite, indépendamment d’une inclusion de nomenclature.','FI-AKI')]
q=''.join('<div class="quiz ui"><p>'+question+'</p><button data-ok="1">'+yes+'</button><button data-ok="0">'+no+'</button><p class="fb" hidden>'+ex+'</p></div>'+ref(sid) for question,yes,no,ex,sid in quiz)
txt=txt.replace('</div></div>',sec('entrainement','S’entraîner : quatre décisions et quatre cas',q+'<p>'+' '.join(w('cas-'+str(i),'Cas '+str(i)) for i in range(1,5))+'</p>',('CH-PROFILES','CH-MEBEKO'))+'</div></div>',1);path.write_text(txt)
save('pop1','\n'.join(pops[:34]));save('pop2','\n'.join(pops[34:]));assert len(pops)==66
print('G24 :66 fenêtres dont14Pareto, quatre cas et quatre quiz rédigés.')
